cssCode:
.scanner-box {
  width: 100px; height: 100px;
  border: 3px solid rgba(0, 210, 255, 0.3);
  border-radius: 20px; position: relative; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
  box-shadow: inset 0 0 20px rgba(0, 210, 255, 0.1);
}
.fingerprint {
  font-size: 50px; color: rgba(0, 210, 255, 0.4);
}
.laser-line {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 3px;
  background: #00d2ff; box-shadow: 0 0 15px 5px rgba(0, 210, 255, 0.5);
  animation: scanLaser 2s infinite ease-in-out alternate;
}
@keyframes scanLaser {
  0% { top: 0; }
  100% { top: 97px; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const box = document.createElement('div');
box.className = 'scanner-box';

const fp = document.createElement('div');
fp.className = 'fingerprint';
fp.innerText = '🔐';

const laser = document.createElement('div');
laser.className = 'laser-line';

box.appendChild(fp);
box.appendChild(laser);
c.appendChild(box);
